import itertools

def compute_energy(seq):
    n = len(seq)
    energy = 0
    C = {}
    for k in range(1, n):
        ck = sum(seq[i] * seq[i+k] for i in range(n-k))
        C[k] = ck
        energy += ck*ck
    return energy, C

solutions = []

# Let's try interpretation 1: seq and c are 0-based.
# seq[1]=1, seq[8]=1
# c[6]=C_7=0, c[9]=C_10=1
for bits in itertools.product([-1, 1], repeat=11):
    seq = list(bits)
    if seq[1] != 1 or seq[8] != 1:
        continue
    energy, C = compute_energy(seq)
    if C[7] != 0 or C[10] != 1:
        continue
    if energy <= 23:
        solutions.append((seq, energy, C))

print("Interpretation 1 (0-based seq) solutions:", len(solutions))
for sol in solutions:
    print(sol[0], "energy:", sol[1], "C:", sol[2])

# Interpretation 2: c is 1-based, so c[6]=C_6=0, c[9]=C_9=1
# seq is 0-based: seq[1]=1, seq[8]=1
solutions2 = []
