    energy, C = compute_energy(seq)
    if C[6] != 0 or C[9] != 1:
        continue
    if energy <= 23:
        solutions2.append((seq, energy, C))

print("Interpretation 2 (c 1-based) solutions:", len(solutions2))
for sol in solutions2:
